299		if err != nil {
300			return false
301		}
302	
303		var hooksFile CursorHooksFile
304		if err := json.Unmarshal(data, &hooksFile); err != nil {
305			return false
306		}
307	
308		return hasEntireHook(hooksFile.Hooks.SessionStart) ||
309			hasEntireHook(hooksFile.Hooks.SessionEnd) ||
310			hasEntireHook(hooksFile.Hooks.BeforeSubmitPrompt) ||
311			hasEntireHook(hooksFile.Hooks.Stop) ||
312			hasEntireHook(hooksFile.Hooks.PreCompact) ||
313			hasEntireHook(hooksFile.Hooks.SubagentStart) ||
314			hasEntireHook(hooksFile.Hooks.SubagentStop)
315	}
