319		return []agent.HookType{
320			agent.HookSessionStart,
321			agent.HookSessionEnd,
322			agent.HookUserPromptSubmit,
323			agent.HookStop,
324			agent.HookPreToolUse,
325			agent.HookPostToolUse,
326		}
327	}
