329	// parseCursorHookType parses a specific hook type from rawHooks into the target slice.
330	// Silently ignores parse errors (leaves target unchanged).
331	func parseCursorHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CursorHookEntry) {
332		if data, ok := rawHooks[hookType]; ok {
333			//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
334			json.Unmarshal(data, target)
335		}
336	}
337	
338	// marshalCursorHookType marshals a hook type back into rawHooks.
339	// If the slice is empty, removes the key from rawHooks.
340	func marshalCursorHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CursorHookEntry) {
341		if len(entries) == 0 {
342			delete(rawHooks, hookType)
343			return
344		}
345		data, err := jsonutil.MarshalWithNoHTMLEscape(entries)
346		if err != nil {
347			return // Silently ignore marshal errors (shouldn't happen)
348		}
349		rawHooks[hookType] = data
350	}
351	
352	// Helper functions for hook management
353	
354	func hookCommandExists(entries []CursorHookEntry, command string) bool {
355		for _, entry := range entries {
356			if entry.Command == command {
357				return true
358			}
359		}
360		return false
361	}
362	
363	func isEntireHook(command string) bool {
364		return agent.IsManagedHookCommand(command, entireHookPrefixes)
365	}
366	
367	func hasEntireHook(entries []CursorHookEntry) bool {
368		for _, entry := range entries {
369			if isEntireHook(entry.Command) {
370				return true
371			}
372		}
373		return false
374	}
375	
376	func removeEntireHooks(entries []CursorHookEntry) []CursorHookEntry {
377		result := make([]CursorHookEntry, 0, len(entries))
378		for _, entry := range entries {
379			if !isEntireHook(entry.Command) {
380				result = append(result, entry)
381			}
382		}
383		return result
384	}
