if absolutePath {
	exe, err := os.Executable()
	if err != nil {
		return "", fmt.Errorf("--absolute-git-hook-path: failed to resolve binary path: %w", err)
	}
	resolved, err := filepath.EvalSymlinks(exe)
	if err != nil {
		// EvalSymlinks can fail on Windows when a path component is an NTFS
		// directory junction rather than a plain symlink — notably Scoop's
		// `…\scoop\apps\<app>\current\` junction, which yields "The system
		// cannot find the path specified" (see issue #1424). The unresolved
		// os.Executable() path is still a valid, launchable absolute path
		// (and on Scoop the stable `current\` path is actually preferable,
		// since it survives version updates that repoint the junction), so
		// fall back to it rather than failing the hook install outright.
		if runtime.GOOS == "windows" {
			return shellQuote(exe), nil
		}
		return "", fmt.Errorf("--absolute-git-hook-path: failed to resolve symlinks for %s: %w", exe, err)
	}
	return shellQuote(resolved), nil
}

